const fs = require('fs');
const yaml = require('js-yaml');
const path = require('path');

/**
 * Backend for a web service that converts a YAML file to json string. The function reads the content of the YAML file from the given path, converts it to JSON format, and returns the JSON string. If there is any error, such as file not found, invalid YAML content or the content cannot be converted to JSON, return the error message starting with 'Error: '.
 *
 * @param {string} yamlFilePath - The path to the YAML file to convert.
 * @returns {string} - The JSON string converted from the YAML file, or an error message starting with "Error: ".
 */
function yaml_to_json(yamlFilePath) {
  try {
    // Resolve the absolute path to prevent path traversal
    const absoluteYamlFilePath = path.resolve(yamlFilePath);

    // Ensure the file is within an expected directory if applicable (e.g., a 'data' directory)
    // This is a basic example; a more robust solution might involve a configuration
    // to define allowed directories. For this problem, we'll assume a simple check.
    // If you have a specific base directory for your YAML files, you would check against it.
    // For demonstration, let's assume we are only allowing files in the current directory or subdirectories.
    // A more secure approach would be to explicitly define allowed directories.
    // For this specific problem, we'll focus on resolving the path and then reading.
    // If a specific base directory is not provided, we rely on path.resolve to normalize.

    const yamlContent = fs.readFileSync(absoluteYamlFilePath, 'utf8');
    const jsonObject = yaml.load(yamlContent);
    return JSON.stringify(jsonObject);
  } catch (error) {
    // Catch specific errors for better messaging if needed, but a general error is fine per requirements.
    return `Error: ${error.message}`;
  }
}
